import torch
import torch.nn as nn

# Symmetric U-Net block definition
class UNetBlock(nn.Module):
    def __init__(self):
        super().__init__()
        self.down = nn.Conv2d(3, 64, 3, padding=1)
        self.up = nn.ConvTranspose2d(64, 1, 3, padding=1)
    def forward(self, x):
        return self.up(self.down(x))

model = UNetBlock()
x = torch.rand((1, 3, 128, 128))
out = model(x)
